betrieb["Mindestfläche_Maßnahme"] := area_requirement
betrieb["Begrünungskombination"] := combination_met
betrieb.Vertragsjahre := contract_years(farm.start_year)
betrieb["Fristen_Düngeaufzeichnung"] := planning_dates(year)
betrieb.Schweinebesatz_erreicht := pig_density_met if farm.pig_option
betrieb.Schweineoption_kombinierbar := pig_combination_met if farm.pig_option
betrieb.Bodenproben_Mindestzahl_Basis := samples_required(farm.zone_ha_mfa_2026)
betrieb.Bodenproben_Mindestzahl_Wien := vienna_samples_required(farm.vienna_ha_mfa_2026) if farm.vienna_option
betrieb.Bodenproben_anrechenbar := count({s.id | some s in farm.samples; sample_valid(s)}) if is_array(farm.samples)
betrieb["Modulationsfaktor_Heimfläche"] := modulation_factor(farm.home_area_ha)
betrieb["AG_prämienfähige_Hektar_maximal"] := input.land.arable_area_ha / 5
betrieb["Flächenabgang_Toleranz_ha"] := loss_tolerance(farm.previous_commitment_ha)
betrieb["Flächenzugang_seit_2025_max_ha"] := addition_limit(farm.commitment_2025_ha) if year >= 2026
betrieb.Schulung_Basis_Stunden := training_hours("Basis", farm.trained_person_id)
betrieb.Schulung_Wien_Stunden := training_hours("Wien", farm.trained_person_id) if farm.vienna_option

parcels_by_id := {p.parcel_id: p | some p in input.land.parcels}
schlag[id].Gebiet := state(p, year) if some id, p in parcels_by_id

schlag[id]["N_Übertrag_mindestens_kg_ha"] := carryover(year, p.gwa.previous_balance, balance_region(p)) if {
	some id, p in parcels_by_id
	zone(p, year)
