hinweise contains finding("planung", null) if date_ns(farm.plan_date) > date_ns(planning_dates(year).plan_due)
hinweise contains finding("planung", null) if date_ns(farm.balance_date) > date_ns(planning_dates(year).balance_due)
hinweise contains finding("konzept", null) if date_ns(farm.water_plan_date) > date_ns("2026-12-31")

hinweise contains finding("wirkstoffe", p.parcel_id) if {
	some p in input.land.parcels
	count(banned_substances(p)) > 0
}

hinweise contains finding("herbst", p.parcel_id) if {
